# generated by autoprobe.py
export PATH=/usr/local/bin:$PATH
[ -d /usr/lib64/openmpi/bin ] && export PATH=/usr/lib64/openmpi/bin:$PATH \
    && export MPI_HOME=/usr/lib64/openmpi
export CPPFLAGS="-I/usr/local/include ${CPPFLAGS:-}"
export LDFLAGS="-L/usr/local/lib -L/usr/local/lib64 ${LDFLAGS:-}"
export LD_LIBRARY_PATH=/usr/local/lib:/usr/local/lib64${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}
export PKG_CONFIG_PATH=/usr/local/lib/pkgconfig:/usr/local/lib64/pkgconfig:/usr/lib64/pkgconfig${PKG_CONFIG_PATH:+:$PKG_CONFIG_PATH}
export CMAKE_PREFIX_PATH=/usr/local:/usr
# "root" dirs many scientific build systems look for (source-built -> /usr/local, RPM -> /usr)
_ap_root() { for p in /usr/local /usr; do [ -e "$p/include/$1" ] && { echo "$p"; return; }; done; echo /usr; }
export HDF5_ROOT=$(_ap_root hdf5.h);   export HDF5_DIR=$HDF5_ROOT;   export HDF5_HOME=$HDF5_ROOT
export GSL_ROOT_DIR=$(_ap_root gsl/gsl_math.h); export GSL_DIR=$GSL_ROOT_DIR; export GSL_HOME=$GSL_ROOT_DIR
export NETCDF_ROOT=$(_ap_root netcdf.h); export NETCDF_DIR=$NETCDF_ROOT
export FFTW_ROOT=$(_ap_root fftw3.h);   export FFTW_DIR=$FFTW_ROOT
export CFITSIO_ROOT=$(_ap_root fitsio.h)
export MPLBACKEND=${MPLBACKEND:-Agg}   # headless matplotlib
[ -f /opt/venv/bin/activate ] && . /opt/venv/bin/activate
